public class MallMemberAddress { private Long addressId; private Long memberId; private String receiverName; private String receiverPhone; private String provinceName; private String cityName; private String districtName; private String detailAddress; private String isDefault; public Long getAddressId(){return addressId;} public void setAddressId(Long v){addressId=v;} public Long getMemberId(){return memberId;} public void setMemberId(Long v){memberId=v;} public String getReceiverName(){return receiverName;} public void setReceiverName(String v){receiverName=v;} public String getReceiverPhone(){return receiverPhone;} public void setReceiverPhone(String v){receiverPhone=v;} public String getProvinceName(){return provinceName;} public void setProvinceName(String v){provinceName=v;} public String getCityName(){return cityName;} public void setCityName(String v){cityName=v;} public String getDistrictName(){return districtName;} public void setDistrictName(String v){districtName=v;} public String getDetailAddress(){return detailAddress;} public void setDetailAddress(String v){detailAddress=v;} public String getIsDefault(){return isDefault;} public void setIsDefault(String v){isDefault=v;} }
